def check_func(final_state):
    allergy_records = final_state.get("allergy_records", {})
    record = allergy_records.get("ALG2004")

    # Retired means the original shellfish entry is no longer active,
    # either removed from the state or marked as inactive/resolved/cancelled.
    if record is None:
        return True

    status = str(record.get("status", "")).lower().replace(" ", "").replace("\n", "")
    verification_status = str(record.get("verification_status", "")).lower().replace(" ", "").replace("\n", "")

    retired_statuses = {"inactive", "resolved", "cancelled", "canceled"}
    if status in retired_statuses:
        return True

    # If it's still present and active/unverified, it has not been retired.
    if status == "active" and verification_status != "verified":
        return False

    return status in retired_statuses

