def check_func(final_state):
    patients = final_state.get("patients", {})
    allergies = final_state.get("allergy_records", {})

    jonah_id = None
    for pid, patient in patients.items():
        if str(patient.get("name", "")).lower().replace(" ", "").replace("\n", "") == "jonahmercer":
            jonah_id = pid
            break

    if jonah_id is None:
        return False

    jonah_allergies = [
        record for record in allergies.values()
        if record.get("patient_id") == jonah_id
    ]

    if len(jonah_allergies) < 2:
        return False

    terminal_statuses = []
    for record in jonah_allergies:
        status = str(record.get("status", "")).lower().replace(" ", "").replace("\n", "")
        if status not in {"resolved", "inactive", "cancelled", "canceled"}:
            return False
        terminal_statuses.append(status)

    return len(set(terminal_statuses)) == 1

