def check_func(final_state):
    """
    Returns True if the allergy records that were changed are attributed to the same
    allergist reviewer (CLN2003). Uses the initial-state allergist identity.
    """
    try:
        allergy_records = final_state.get("allergy_records", {})
        if not isinstance(allergy_records, dict):
            return False

        reviewer_id = "CLN2003"

        # Check all allergy records that appear review-normalized in final state.
        # The task concerns changed records; the consistent reviewer must be the allergist.
        for record in allergy_records.values():
            if not isinstance(record, dict):
                return False

            recorded_by = str(record.get("recorded_by", "")).lower().replace(" ", "").replace("\n", "")
            verification_status = str(record.get("verification_status", "")).lower().replace(" ", "").replace("\n", "")
            status = str(record.get("status", "")).lower().replace(" ", "").replace("\n", "")

            # If the record is part of the review-ready normalized set, it should be attributed
            # to the allergist reviewer from the initial state.
            if verification_status in {"verified", "reviewed"} or status in {"active", "resolved", "inactive"}:
                if recorded_by != reviewer_id.lower().replace(" ", "").replace("\n", ""):
                    return False

        return True
    except Exception:
        return False

